     /* HEADER */ 
     .header { height: 78px; 
     background: #102957; color: white; display: flex; align-items: center; justify-content: space-between; padding: 0 30px; } .brand { display: flex; flex-direction: column; } .brand h1 { font-size: 27px; line-height: 1; color: white; } .brand h1 span { color: #159fe5; } .brand p { margin-top: 6px; font-size: 13px; color: #d5e0f0; } .header-right { text-align: right; } .header-right strong { display: block; font-size: 14px; } .header-right span { display: block; margin-top: 5px; font-size: 12px; color: #cbd8ea; } /* PAGE */ .page { width: 100%; max-width: 1150px; margin: 0 auto; padding: 30px 20px 50px; } /* EXAM CARD */ .exam-card { background: white; border: 1px solid #e5ebf3; border-radius: 12px; padding: 28px 30px; box-shadow: 0 2px 8px rgba(20, 50, 90, 0.04); margin-bottom: 20px; } .exam-title-row { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; margin-bottom: 25px; } .exam-title h1 { font-size: 28px; color: #1d3557; margin-bottom: 7px; } .exam-title p { color: #718198; font-size: 14px; } .exam-status { background: #e7f8ef; color: #1b8a50; padding: 7px 13px; border-radius: 20px; font-size: 12px; font-weight: 600; white-space: nowrap; } /* EXAM INFO */ .exam-info { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; } .info-box { background: #fafcff; border: 1px solid #e5ebf3; border-radius: 8px; padding: 15px 18px; } .info-box p { color: #718198; font-size: 12px; margin-bottom: 6px; } .info-box strong { color: #1d3557; font-size: 16px; } /* TIMER */ .timer-card { background: white; border: 1px solid #e5ebf3; border-radius: 12px; padding: 18px 25px; display: flex; align-items: center; justify-content: space-between; box-shadow: 0 2px 8px rgba(20, 50, 90, 0.04); margin-bottom: 20px; } .timer-section { display: flex; align-items: center; gap: 15px; } .timer-icon { width: 40px; height: 40px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 20px; color: #159fe5; background: #eaf4ff; } .timer-label { font-size: 13px; color: #718198; margin-bottom: 3px; } #timer { font-size: 25px; font-weight: 700; color: #1d3557; letter-spacing: 1px; } #timer.warning { color: #d98c00; } #timer.danger { color: #d63031; } /* EXAM AREA */ .exam-area { display: grid; grid-template-columns: minmax(0, 1fr) 280px; gap: 20px; align-items: start; } /* QUESTION CARD */ .question-card { background: white; border: 1px solid #e5ebf3; border-radius: 12px; padding: 30px; box-shadow: 0 2px 8px rgba(20, 50, 90, 0.04); } .question-item { display: none; } .question-item.active { display: block; } .question-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 28px; } .question-number { color: #159fe5; font-size: 14px; font-weight: 700; } .question-marks { color: #159fe5; font-size: 13px; font-weight: 600; } .question-text { font-size: 19px; line-height: 1.5; color: #1d3557; margin-bottom: 25px; } /* OPTIONS */ .options { display: flex; flex-direction: column; gap: 11px; } .option-label { display: flex; align-items: center; border: 1px solid #e2e8f0; border-radius: 9px; padding: 13px 15px; cursor: pointer; transition: 0.2s; background: white; } .option-label:hover { border-color: #159fe5; background: #f8fcff; } .option-label.selected { border-color: #159fe5; background: #eef8ff; } .option-radio { position: absolute; opacity: 0; } .option-letter { width: 31px; height: 31px; min-width: 31px; border-radius: 50%; background: #f0f3f7; display: flex; align-items: center; justify-content: center; margin-right: 13px; color: #526781; font-size: 13px; font-weight: 700; } .option-label.selected .option-letter { background: #159fe5; color: white; } .option-text { font-size: 14px; color: #455a73; line-height: 1.4; } /* NAVIGATION */ .question-navigation { display: flex; align-items: center; justify-content: space-between; margin-top: 28px; padding-top: 22px; border-top: 1px solid #edf1f5; gap: 10px; } .nav-left, .nav-right { display: flex; gap: 10px; } .nav-button { border: 1px solid #dce4ed; background: white; color: #526781; padding: 10px 22px; border-radius: 7px; font-size: 13px; font-weight: 600; cursor: pointer; } .nav-button:hover { border-color: #159fe5; color: #159fe5; } .nav-button.next { background: #159fe5; border-color: #159fe5; color: white; } .nav-button.next:hover { background: #118bc9; } .nav-button.submit { background: #1b8a50; border-color: #1b8a50; color: white; } .nav-button.submit:hover { background: #157642; } .nav-button:disabled { opacity: 0.5; cursor: not-allowed; } /* NAVIGATOR */ .navigator { background: white; border: 1px solid #e5ebf3; border-radius: 12px; padding: 22px; box-shadow: 0 2px 8px rgba(20, 50, 90, 0.04); position: sticky; top: 20px; } .navigator h3 { font-size: 16px; color: #1d3557; margin-bottom: 7px; } .navigator p { color: #718198; font-size: 12px; margin-bottom: 18px; } .question-buttons { display: grid; grid-template-columns: repeat(5, 1fr); gap: 8px; } .question-button { height: 38px; width: 38px; border: 1px solid #dce4ed; background: white; border-radius: 7px; color: #526781; cursor: pointer; font-size: 13px; font-weight: 600; } .question-button:hover { border-color: #159fe5; color: #159fe5; } .question-button.current { background: #159fe5; border-color: #159fe5; color: white; } .question-button.answered { background: #dff7ec; border-color: #b9e9d0; color: #1b8a50; } .question-button.current.answered { background: #159fe5; border-color: #159fe5; color: white; } /* LEGEND */ .legend { margin-top: 22px; padding-top: 18px; border-top: 1px solid #edf1f5; } .legend-item { display: flex; align-items: center; gap: 9px; margin-bottom: 11px; color: #718198; font-size: 12px; } .legend-dot { width: 13px; height: 13px; border-radius: 3px; } .dot-current { background: #159fe5; } .dot-answered { background: #8ed8b4; } .dot-empty { background: #eef1f4; border: 1px solid #dce3ea; } /* NO QUESTIONS */ .no-questions { text-align: center; padding: 60px 20px; } .no-questions-icon { font-size: 42px; margin-bottom: 15px; } .no-questions h2 { color: #526781; margin-bottom: 8px; } .no-questions p { color: #718198; font-size: 14px; } /* RESPONSIVE */ @media (max-width: 900px) { .exam-area { grid-template-columns: 1fr; } .navigator { position: static; } .question-buttons { grid-template-columns: repeat(8, 1fr); } } @media (max-width: 700px) { .header { padding: 0 18px; } .brand h1 { font-size: 22px; } .brand p { font-size: 11px; } .header-right strong { font-size: 12px; } .header-right span { display: none; } .page { padding: 20px 12px 40px; } .exam-card { padding: 22px; } .exam-title-row { flex-direction: column; } .exam-info { grid-template-columns: 1fr; } .timer-card { align-items: flex-start; } .question-card { padding: 22px; } .question-text { font-size: 17px; } .question-buttons { grid-template-columns: repeat(5, 1fr); } .question-navigation { flex-direction: column; align-items: stretch; } .nav-left, .nav-right { width: 100%; } .nav-button { flex: 1; } } </style> </head> <body> <!-- HEADER --> <header class="header"> <div class="brand"> <h1> Skill<span>Test</span> </h1> <p> AI & Digital Transformation </p> </div> <div class="header-right"> <strong> Student Examination </strong> <span> {{ session('student_name') }} </span> </div> </header> <div class="page"> <!-- EXAM INFORMATION --> <div class="exam-card"> <div class="exam-title-row"> <div class="exam-title"> <h1> {{ $examPaper->subject ?? 'Examination' }} </h1> <p> Answer all questions carefully and submit your examination before the time expires. </p> </div> <div class="exam-status"> Examination In Progress </div> </div> <div class="exam-info"> <div class="info-box"> <p> Duration </p> <strong> {{ $examPaper->duration ?? 0 }} minutes </strong> </div> <div class="info-box"> <p> Total Marks </p> <strong> {{ $examPaper->total_marks ?? 0 }} </strong> </div> <div class="info-box"> <p> Questions </p> <strong> {{ $examQuestions->count() }} </strong> </div> </div> </div> <!-- TIMER --> <div class="timer-card"> <div class="timer-section"> <div class="timer-icon"> ⏱ </div> <div> <div class="timer-label"> Time Remaining </div> <div id="timer"> 00:00 </div> </div> </div> </div> <!-- EXAM FORM --> <form id="examForm" action="{{ url('/student/exam/' . $assignment->id . '/submit') }}" method="POST" > @csrf <div class="exam-area"> <!-- QUESTIONS --> <div class="question-card"> @if($examQuestions->count() > 0) @foreach($examQuestions as $index => $q) <div class="question-item {{ $index === 0 ? 'active' : '' }}" id="question{{ $index }}" > <div class="question-header"> <span class="question-number"> Question {{ $index + 1 }} of {{ $examQuestions->count() }} </span> <span class="question-marks"> {{ $q->marks ?? 1 }} Marks </span> </div> <h2 class="question-text"> {{ $q->question }} </h2> <div class="options"> <!-- A --> <label class="option-label"> <input type="radio" class="option-radio" name="answers[{{ $q->id }}]" value="A" > <span class="option-letter"> A </span> <span class="option-text"> {{ $q->option_a }} </span> </label> <!-- B --> <label class="option-label"> <input type="radio" class="option-radio" name="answers[{{ $q->id }}]" value="B" > <span class="option-letter"> B </span> <span class="option-text"> {{ $q->option_b }} </span> </label> <!-- C --> <label class="option-label"> <input type="radio" class="option-radio" name="answers[{{ $q->id }}]" value="C" > <span class="option-letter"> C </span> <span class="option-text"> {{ $q->option_c }} </span> </label> <!-- D --> <label class="option-label"> <input type="radio" class="option-radio" name="answers[{{ $q->id }}]" value="D" > <span class="option-letter"> D </span> <span class="option-text"> {{ $q->option_d }} </span> </label> </div> <!-- QUESTION NAVIGATION --> <div class="question-navigation"> <div class="nav-left"> <button type="button" class="nav-button" onclick="previousQuestion()" id="previousButton" > Previous </button> </div> <div class="nav-right"> @if($index < $examQuestions->count() - 1) <button type="button" class="nav-button next" onclick="nextQuestion()" > Next </button> @else <button type="button" class="nav-button submit" onclick="confirmSubmit()" > Submit Exam </button> @endif </div> </div> </div> @endforeach @else <div class="no-questions"> <div class="no-questions-icon"> 📝 </div> <h2> No Questions Available </h2> <p> This examination currently does not contain any questions. </p> </div> @endif </div> <!-- QUESTION NAVIGATOR --> @if($examQuestions->count() > 0) <aside class="navigator"> <h3> Questions </h3> <p> Click a number to navigate </p> <div class="question-buttons"> @foreach($examQuestions as $index => $examQuestion) <button type="button" class="question-button {{ $index === 0 ? 'current' : '' }}" id="questionButton{{ $index }}" onclick="showQuestion({{ $index }})" > {{ $index + 1 }} </button> @endforeach </div> <div class="legend"> <div class="legend-item"> <span class="legend-dot dot-current"></span> Current Question </div> <div class="legend-item"> <span class="legend-dot dot-answered"></span> Answered </div> <div class="legend-item"> <span class="legend-dot dot-empty"></span> Not Answered </div> </div> </aside> @endif </div> </form> </div> <script> /* |-------------------------------------------------------------------------- | QUESTIONS |-------------------------------------------------------------------------- */ let currentQuestion = 0; const questions = document.querySelectorAll( '.question-item' ); const questionButtons = document.querySelectorAll( '.question-button' ); const totalQuestions = questions.length; /* |-------------------------------------------------------------------------- | SHOW QUESTION |-------------------------------------------------------------------------- */ function showQuestion(index) { if ( index < 0 || index >= totalQuestions ) { return; } questions.forEach(function(question) { question.classList.remove( 'active' ); }); questions[index] .classList.add('active'); questionButtons.forEach( function(button, buttonIndex) { button.classList.remove( 'current' ); if ( buttonIndex === index ) { button.classList.add( 'current' ); } } ); currentQuestion = index; updateAnsweredButtons(); updatePreviousButton(); } /* |-------------------------------------------------------------------------- | NEXT |-------------------------------------------------------------------------- */ function nextQuestion() { if ( currentQuestion < totalQuestions - 1 ) { showQuestion( currentQuestion + 1 ); } } /* |-------------------------------------------------------------------------- | PREVIOUS |-------------------------------------------------------------------------- */ function previousQuestion() { if ( currentQuestion > 0 ) { showQuestion( currentQuestion - 1 ); } } /* |-------------------------------------------------------------------------- | PREVIOUS BUTTON |-------------------------------------------------------------------------- */ function updatePreviousButton() { const button = document.getElementById( 'previousButton' ); if (!button) { return; } button.disabled = currentQuestion === 0; } /* |-------------------------------------------------------------------------- | CHECK ANSWER |-------------------------------------------------------------------------- */ function isQuestionAnswered(index) { const question = questions[index]; if (!question) { return false; } return question.querySelector( 'input[type="radio"]:checked' ) !== null; } /* |-------------------------------------------------------------------------- | UPDATE QUESTION BUTTONS |-------------------------------------------------------------------------- */ function updateAnsweredButtons() { questions.forEach( function(question, index) { const button = document.getElementById( 'questionButton' + index ); if (!button) { return; } if ( isQuestionAnswered(index) ) { button.classList.add( 'answered' ); } else { button.classList.remove( 'answered' ); } } ); } /* |-------------------------------------------------------------------------- | OPTION SELECTION |-------------------------------------------------------------------------- */ document .querySelectorAll('.option-radio') .forEach(function(radio) { radio.addEventListener( 'change', function() { const question = this.closest( '.question-item' ); if (question) { question .querySelectorAll( '.option-label' ) .forEach( function(option) { option.classList .remove( 'selected' ); } ); } const parent = this.closest( '.option-label' ); if (parent) { parent.classList.add( 'selected' ); } updateAnsweredButtons(); } ); }); /* |-------------------------------------------------------------------------- | TIMER |-------------------------------------------------------------------------- */ let remainingSeconds = {{ (int) $remainingSeconds }}; function formatTime(seconds) { seconds = Math.max( 0, seconds ); const minutes = Math.floor( seconds / 60 ); const secs = seconds % 60; return String(minutes) .padStart(2, '0') + ':' + String(secs) .padStart(2, '0'); } function updateTimer() { const timer = document.getElementById( 'timer' ); if (!timer) { return; } timer.innerText = formatTime( remainingSeconds ); /* |-------------------------------------------------------------------------- | Timer Warning |-------------------------------------------------------------------------- */ timer.classList.remove( 'warning', 'danger' ); if ( remainingSeconds <= 60 ) { timer.classList.add( 'danger' ); } else if ( remainingSeconds <= 300 ) { timer.classList.add( 'warning' ); } /* |-------------------------------------------------------------------------- | TIME FINISHED |-------------------------------------------------------------------------- */ if ( remainingSeconds <= 0 ) { clearInterval( timerInterval ); examSubmitted = true; const form = document.getElementById( 'examForm' ); if (form) { form.submit(); } return; } remainingSeconds--; } updateTimer(); const timerInterval = setInterval( function() { updateTimer(); }, 1000 ); /* |-------------------------------------------------------------------------- | SUBMIT CONFIRMATION |-------------------------------------------------------------------------- */ function confirmSubmit() { let answered = 0; questions.forEach( function(question) { const selected = question.querySelector( 'input[type="radio"]:checked' ); if (selected) { answered++; } } ); const unanswered = totalQuestions - answered; let message = 'Are you sure you want to submit your examination?'; if ( unanswered > 0 ) { message = 'You have ' + unanswered + ' unanswered question' + ( unanswered > 1 ? 's' : '' ) + '.\n\n' + 'Are you sure you want to submit your examination?'; } if ( confirm(message) ) { examSubmitted = true; document .getElementById( 'examForm' ) .submit(); } } /* |-------------------------------------------------------------------------- | PREVENT ACCIDENTAL REFRESH |-------------------------------------------------------------------------- */ let examSubmitted = false; const examForm = document.getElementById( 'examForm' ); if (examForm) { examForm.addEventListener( 'submit', function() { examSubmitted = true; } ); } window.addEventListener( 'beforeunload', function(event) { if (!examSubmitted) { event.preventDefault(); event.returnValue = ''; } } ); /* |-------------------------------------------------------------------------- | INITIAL STATE |-------------------------------------------------------------------------- */ if ( totalQuestions > 0 ) { showQuestion(0); } </script> </body> </html>